/* Anthropic DNA — warm cream, book-like serif display, terracotta accent */
.theme-anthropic-dna {
  --bg: oklch(0.982 0.005 95.1);
  --surface: oklch(0.948 0.011 95.2);
  --surface-2: oklch(0.94 0.016 82);
  --fg: oklch(0.191 0.002 106.6);
  --fg-muted: oklch(0.619 0.010 100.1);
  --accent: oklch(0.672 0.131 38.8);
  --accent-fg: oklch(0.99 0.008 85);
  --accent-2: oklch(0.45 0.05 150);
  --line: oklch(0.86 0.015 80);
  --success: oklch(0.55 0.11 150);
  --warning: oklch(0.72 0.14 75);
  --danger: oklch(0.53 0.17 28);

  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.875rem;
  --radius-pill: 9999px;

  --shadow-1: 0 1px 2px oklch(0.3 0.03 60 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0.3 0.03 60 / 16%);
  --shadow-3: 0 24px 56px -24px oklch(0.3 0.03 60 / 24%);
  --glow: 0 0 0 3px color-mix(in oklab, var(--accent) 25%, transparent);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Source Serif 4", Georgia, serif;
  --font-body: "Archivo", "Inter", sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;

  --tracking-display: -0.02em;
  --label-transform: none;
  --label-tracking: 0.01em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
  line-height: 1.7;
}

.theme-anthropic-dna h1,
.theme-anthropic-dna h2,
.theme-anthropic-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 500;
  line-height: 1.15;
}

/* signature */
.theme-anthropic-dna { background-image: radial-gradient(oklch(0.5 0.02 80 / 4%) 1px, transparent 1px); background-size: 6px 6px; }
.theme-anthropic-dna h1 { font-weight: 500; }
.theme-anthropic-dna a { text-decoration: underline; text-underline-offset: 3px; }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
